-- Initial import of "Infra Tracker.xlsx" (Consolidated Tracker and Plan 27 Projects sheets).

UPDATE tracker_tasks SET completed_at = now() WHERE status = 'Completed' AND completed_at IS NULL;
SELECT id, 'created', 'Imported from the consolidated Excel tracker.' FROM tracker_tasks t
WHERE NOT EXISTS (SELECT 1 FROM tracker_task_updates u WHERE u.task_id = t.id);
